INSERT INTO `job_categories` VALUES (1,'2026-09-02 02:43:40.522704','admin@gmail.com','Lĩnh vực công nghệ thông tin, phát triển phần mềm và các giải pháp kỹ thuật số',0,'Công nghệ thông tin / Phần mềm','ACTIVE','2026-09-02 02:43:40.522704','admin@gmail.com',NULL),(2,'2026-09-02 02:45:17.226536','admin@gmail.com','Thiết kế, phát triển, kiểm thử và bảo trì các ứng dụng và hệ thống phần mềm',1,'Lập trình viên / Kỹ sư phần mềm (Software Engineer / Developer)','ACTIVE','2026-09-02 02:45:17.226536','admin@gmail.com',1),(3,'2026-09-02 02:47:18.076197','admin@gmail.com','Chuyên thiết kế và xây dựng giao diện tương tác trực tiếp với người dùng trên trình duyệt web hoặc ứng dụng di động, sử dụng các công nghệ như React, Vue.js, Angular, HTML, CSS và JavaScript',2,'Frontend Developer','ACTIVE','2026-09-02 02:47:18.076197','admin@gmail.com',2),(4,'2026-09-02 02:52:35.232440','admin@gmail.com','Xây dựng phần logic cốt lõi hoạt động phía sau máy chủ, thiết kế cơ sở dữ liệu và phát triển hệ thống API để giao tiếp với frontend, sử dụng các ngôn ngữ như Java, Python, Node.js, C#, Go',2,'Backend Developer','ACTIVE','2026-09-02 02:52:35.232440','admin@gmail.com',2),(5,'2026-09-02 02:53:54.008491','admin@gmail.com','Đảm nhận cả hai vai trò frontend và backend, có khả năng tự xây dựng và hoàn thiện một ứng dụng từ giao diện người dùng cho đến hệ thống cơ sở dữ liệu dưới máy chủ',2,'Full-stack Developer','ACTIVE','2026-09-02 02:53:54.008491','admin@gmail.com',2),(6,'2026-09-02 02:53:58.950897','admin@gmail.com','Chuyên phát triển ứng dụng di động chạy trên hệ điều hành iOS hoặc Android, sử dụng ngôn ngữ gốc (Swift, Kotlin) hoặc các framework đa nền tảng (Flutter, React Native)',2,'Mobile Developer','ACTIVE','2026-09-02 02:53:58.950897','admin@gmail.com',2),(7,'2026-09-02 02:54:05.078787','admin@gmail.com','Lập trình phần mềm nhúng điều khiển cho các thiết bị phần cứng, vi điều khiển, hệ thống IoT, ô tô thông minh và các thiết bị điện tử gia dụng',2,'Embedded Software Engineer','ACTIVE','2026-09-02 02:54:05.078787','admin@gmail.com',2),(8,'2026-09-02 03:05:21.231210','admin@gmail.com','Nghiên cứu, phát triển và ứng dụng các công nghệ trí tuệ nhân tạo, học máy và hệ thống thông minh',1,'Kỹ sư Trí tuệ nhân tạo và Học máy (AI / Machine Learning Engineer)','ACTIVE','2026-09-02 03:05:21.231210','admin@gmail.com',1),(9,'2026-09-02 03:05:51.035754','admin@gmail.com','Xây dựng, huấn luyện và tối ưu hóa các thuật toán học máy để máy tính có thể tự học từ dữ liệu và đưa ra dự đoán',2,'Machine Learning Engineer','ACTIVE','2026-09-02 03:05:51.035754','admin@gmail.com',8),(10,'2026-09-02 03:09:20.733031','admin@gmail.com','Chuyên sâu về mạng neural nhân tạo, xử lý và phân tích hình ảnh, video, nhận diện khuôn mặt hoặc các hệ thống thị giác máy tính',2,'Deep Learning / Computer Vision Engineer','ACTIVE','2026-09-02 03:09:20.733031','admin@gmail.com',8),(11,'2026-09-02 03:09:33.537460','admin@gmail.com','Phát triển các hệ thống xử lý ngôn ngữ tự nhiên, hiểu và sinh văn bản, chatbot thông minh và các mô hình ngôn ngữ lớn (LLM)',2,'NLP Engineer (Natural Language Processing)','ACTIVE','2026-09-02 03:09:33.537460','admin@gmail.com',8),(12,'2026-09-02 03:09:38.102623','admin@gmail.com','Tập trung nghiên cứu và ứng dụng các mô hình tạo sinh (như Diffusion models, Transformers) để tạo ra nội dung văn bản, hình ảnh, âm thanh hoặc mã nguồn mới',2,'Generative AI Engineer','ACTIVE','2026-09-02 03:09:38.102623','admin@gmail.com',8),(13,'2026-09-02 03:12:15.229129','admin@gmail.com','Thiết kế, xây dựng, kiểm tra và bảo trì các hệ thống kiến trúc dữ liệu, đường ống xử lý dữ liệu lớn (Data Pipeline)',1,'Kỹ sư Dữ liệu (Data Engineer)','ACTIVE','2026-09-02 03:12:15.229129','admin@gmail.com',1),(14,'2026-09-02 03:13:50.773404','admin@gmail.com','Thiết kế, xây dựng và duy trì các đường ống dữ liệu (data pipeline) để thu thập, chuyển đổi và vận chuyển dữ liệu từ nhiều nguồn khác nhau',2,'Data Pipeline Engineer','ACTIVE','2026-09-02 03:13:50.773404','admin@gmail.com',13),(15,'2026-09-02 03:13:57.390622','admin@gmail.com','Quản lý và xử lý các tập dữ liệu có quy mô cực lớn (Big Data) bằng các công cụ phân distributed computing như Hadoop, Spark, Kafka',2,'Big Data Engineer','ACTIVE','2026-09-02 03:13:57.390622','admin@gmail.com',13),(16,'2026-09-02 03:14:07.750757','admin@gmail.com','Xây dựng và tối ưu hóa các hệ thống kho dữ liệu trung tâm (Data Warehouse, Data Lakehouse) phục vụ cho việc lưu trữ và truy vấn doanh nghiệp',2,'Data Warehouse Engineer','ACTIVE','2026-09-02 03:14:07.750757','admin@gmail.com',13),(17,'2026-09-02 03:14:54.715217','admin@gmail.com','Thu thập, xử lý và phân tích dữ liệu để tìm ra các thông tin chi tiết (insights), xây dựng mô hình dự đoán và hỗ trợ ra quyết định chiến lược',1,'Chuyên gia phân tích dữ liệu và Khoa học dữ liệu (Data Analyst / Scientist)','ACTIVE','2026-09-02 03:14:54.715217','admin@gmail.com',1),(18,'2026-09-02 03:15:53.749598','admin@gmail.com','Khai thác, làm sạch và phân tích dữ liệu sẵn có để tạo ra các báo cáo trực quan (Dashboard), giúp cấp quản lý đưa ra quyết định kinh doanh hàng ngày',2,'Data Analyst','ACTIVE','2026-09-02 03:15:53.749598','admin@gmail.com',17),(19,'2026-09-02 03:16:01.245798','admin@gmail.com','Sử dụng toán học, thống kê nâng cao và mô hình máy tính để tìm ra các insight ẩn giấu, xây dựng mô hình dự báo hành vi hoặc xu hướng tương lai',2,'Data Scientist','ACTIVE','2026-09-02 03:16:01.245798','admin@gmail.com',17),(20,'2026-09-02 03:16:08.979652','admin@gmail.com','Chuyên thiết kế các hệ thống phân tích kinh doanh, tối ưu hóa các chỉ số hiệu suất (KPI) và quản lý luồng thông tin chiến lược cho doanh nghiệp',2,'Business Intelligence (BI) Analyst','ACTIVE','2026-09-02 03:16:08.979652','admin@gmail.com',17),(21,'2026-09-02 03:17:01.028742','admin@gmail.com','Tự động hóa quy trình triển khai phần mềm, quản lý hạ tầng và đảm bảo tính ổn định, độ sẵn sàng cao cho hệ thống',1,'Kỹ sư DevOps / SRE (DevOps / Site Reliability Engineer)','ACTIVE','2026-09-02 03:17:01.028742','admin@gmail.com',1),(22,'2026-09-02 03:17:45.003002','admin@gmail.com','Tự động hóa quy trình tích hợp và triển khai liên tục (CI/CD), quản lý công cụ quản lý mã nguồn và đẩy nhanh tốc độ phát hành sản phẩm',2,'DevOps Engineer','ACTIVE','2026-09-02 03:17:45.003002','admin@gmail.com',21),(23,'2026-09-02 03:17:55.135628','admin@gmail.com','Thiết kế, cấu hình và quản lý hạ tầng công nghệ trên các nền tảng điện toán đám mây lớn như AWS, Microsoft Azure, Google Cloud Platform',2,'Cloud Engineer','ACTIVE','2026-09-02 03:17:55.135628','admin@gmail.com',21),(24,'2026-09-02 03:18:31.970029','admin@gmail.com','Bảo vệ hệ thống mạng, dữ liệu và ứng dụng khỏi các mối đe dọa và tấn công mạng, đảm bảo an toàn thông tin và bảo mật cho doanh nghiệp',1,'Chuyên gia An toàn thông tin (Cybersecurity Specialist)','ACTIVE','2026-09-02 03:18:31.970029','admin@gmail.com',1),(25,'2026-09-02 03:19:16.422192','admin@gmail.com','Chủ động tấn công mô phỏng vào hệ thống để tìm ra các lỗ hổng bảo mật trước khi bị kẻ xấu lợi dụng',2,'Pentester (Penetration Tester / Ethical Hacker)','ACTIVE','2026-09-02 03:19:16.422192','admin@gmail.com',24),(26,'2026-09-02 03:19:23.401045','admin@gmail.com','Thiết kế các lớp phòng thủ, tường lửa, mã hóa dữ liệu và xây dựng chính sách bảo mật tổng thể cho tổ chức',2,'Security Architect / Engineer','ACTIVE','2026-09-02 03:19:23.401045','admin@gmail.com',24),(27,'2026-09-02 03:20:12.912308','admin@gmail.com','Kiểm tra, phát hiện lỗi và đảm bảo chất lượng phần mềm trước khi sản phẩm được phát hành đến người dùng',1,'Kỹ sư Kiểm thử phần mềm (QA / QC Engineer)','ACTIVE','2026-09-02 03:20:12.912308','admin@gmail.com',1),(28,'2026-09-02 03:21:31.450897','admin@gmail.com','Thực hiện kiểm thử thủ công dựa trên kịch bản (test case) để tìm ra các lỗi giao diện hoặc logic của phần mềm',2,'Manual Tester','ACTIVE','2026-09-02 03:21:31.450897','admin@gmail.com',27),(29,'2026-09-02 03:21:38.730511','admin@gmail.com','Viết các đoạn mã kiểm thử tự động để chạy lại các kịch bản kiểm tra nhanh chóng, tiết kiệm thời gian cho các dự án lớn',2,'Automation Tester','ACTIVE','2026-09-02 03:21:38.730511','admin@gmail.com',27),(30,'2026-09-02 03:21:42.982556','admin@gmail.com','Đảm bảo toàn bộ quy trình phát triển phần mềm tuân thủ các tiêu chuẩn chất lượng đã đề ra',2,'QA Manager / Engineer','ACTIVE','2026-09-02 03:21:42.982556','admin@gmail.com',27),(31,'2026-09-02 03:22:12.168367','admin@gmail.com','Nghiên cứu hành vi người dùng, thiết kế giao diện trực quan và tối ưu hóa trải nghiệm người dùng trên các nền tảng số',1,'Thiết kế giao diện và trải nghiệm người dùng (UI/UX Designer)','ACTIVE','2026-09-02 03:22:12.168367','admin@gmail.com',1),(32,'2026-09-02 03:23:04.450237','admin@gmail.com','Nghiên cứu tâm lý, hành vi, nhu cầu và nỗi đau của người dùng thông qua phỏng vấn, khảo sát và phân tích dữ liệu',2,'UX Researcher','ACTIVE','2026-09-02 03:23:04.450237','admin@gmail.com',31),(33,'2026-09-02 03:23:14.696313','admin@gmail.com','Thiết kế chi tiết giao diện trực quan, màu sắc, font chữ, bố cục và hệ thống thiết kế (Design System) cho web và ứng dụng',2,'UI Designer','ACTIVE','2026-09-02 03:23:14.696313','admin@gmail.com',31),(34,'2026-09-02 03:23:49.350728','admin@gmail.com','Lên chiến lược, định hướng phát triển sản phẩm công nghệ và quản lý tiến độ, nguồn lực dự án để đảm bảo hoàn thành mục tiêu đề ra',1,'Quản lý sản phẩm và dự án (Product / Project Manager)','ACTIVE','2026-09-02 03:23:49.350728','admin@gmail.com',1),(35,'2026-09-02 03:24:38.884365','admin@gmail.com','Nghiên cứu thị trường, định hướng tầm nhìn, lập chiến lược phát triển và quyết định tính năng cho sản phẩm công nghệ',2,'Product Manager (PM)','ACTIVE','2026-09-02 03:24:38.884365','admin@gmail.com',34),(36,'2026-09-02 03:24:51.166001','admin@gmail.com','Lập kế hoạch, quản lý ngân sách, phân bổ nguồn lực và theo dõi tiến độ để đảm bảo dự án hoàn thành đúng hạn',2,'Project Manager (PrM)','ACTIVE','2026-09-02 03:24:51.166001','admin@gmail.com',34);
