INSERT INTO `job_recommendation_items` VALUES (1,'2026-09-14 14:52:02.473862','Ứng viên có kỹ năng Java, Spring Boot và kinh nghiệm thực tế về Authentication & Authorization trong các dự án cá nhân. Mặc dù là Fresher nhưng có nền tảng kỹ thuật tốt, tuy nhiên vị trí này yêu cầu 3 năm kinh nghiệm nên cần thời gian học hỏi thêm. Địa điểm tại Hà Nội phù hợp với ứng viên.',85.00,'[\"Java\",\"Spring Boot\",\"Authentication & Authorization\"]','[\"Angular\"]',1,74,1),(2,'2026-09-14 14:52:02.473862','Phù hợp tốt với yêu cầu kỹ thuật Java, Spring Boot và SQL. Ứng viên có dự án thực tế bao gồm database design. Điểm hạn chế duy nhất là địa điểm tại Đà Nẵng, ứng viên cần làm việc trực tiếp tại đó.',85.00,'[\"Java\",\"Spring Boot\",\"SQL & Database Design\"]','[]',2,14,1),(3,'2026-09-14 14:52:02.473862','Phù hợp với cấp độ Fresher của ứng viên. Ứng viên có kỹ năng ReactJS, HTML, CSS và JavaScript. Thiếu bằng chứng cụ thể về Web Performance Optimization nhưng nền tảng học tập tốt.',80.00,'[\"ReactJS\",\"JavaScript (ES6+)\",\"HTML5 / CSS3\"]','[\"Web Performance Optimization\"]',3,69,1),(4,'2026-09-14 14:52:02.473862','Ứng viên có Java, Spring Boot, Apache Kafka (Message Queue) và Authentication. Kinh nghiệm chưa đạt cấp Senior và thiếu kỹ năng Angular. Tuy nhiên, kiến thức về hệ thống banking của ứng viên là điểm cộng lớn cho vị trí này.',75.00,'[\"Java\",\"Spring Boot\",\"Message Queue (RabbitMQ / Kafka)\",\"Authentication & Authorization\"]','[\"Angular\"]',4,63,1),(5,'2026-09-14 14:52:02.473862','Ứng viên có kỹ năng ReactJS và hiểu biết về bảo mật hệ thống. Tuy nhiên, thiếu hụt kỹ năng Node.js và SQL (cần kiểm chứng thêm kinh nghiệm database thực tế). Vị trí Middle yêu cầu 3 năm kinh nghiệm trong khi ứng viên đang là Fresher.',70.00,'[\"ReactJS\",\"Authentication & Authorization\"]','[\"Node.js\",\"SQL & Database Design\"]',5,71,1);
/*!40000 ALTER TABLE `job_recommendation_items` ENABLE KEYS */;
UNLOCK TABLES;

