--
-- Table structure for table `jobs`
--

DROP TABLE IF EXISTS `jobs`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `jobs` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `applied_count` int DEFAULT NULL,
  `benefits` mediumtext,
  `competition_level` enum('HIGH','LOW','MEDIUM') NOT NULL,
  `created_at` datetime(6) DEFAULT NULL,
  `created_by` varchar(100) DEFAULT NULL,
  `deleted` bit(1) NOT NULL,
  `deleted_at` datetime(6) DEFAULT NULL,
  `deleted_by` varchar(255) DEFAULT NULL,
  `description` mediumtext NOT NULL,
  `end_date` datetime(6) NOT NULL,
  `experience_required` int DEFAULT NULL,
  `how_to_apply` text,
  `level` enum('DIRECTOR','FRESHER','INTERN','JUNIOR','LEAD','MANAGER','MIDDLE','SENIOR') DEFAULT NULL,
  `location` varchar(255) NOT NULL,
  `name` varchar(255) NOT NULL,
  `negotiable` bit(1) NOT NULL,
  `quantity` int NOT NULL,
  `requirement` mediumtext,
  `responsibility` mediumtext,
  `salary_max` double NOT NULL,
  `salary_min` double NOT NULL,
  `start_date` datetime(6) NOT NULL,
  `status` enum('CLOSED','DELETED','DRAFT','EXPIRED','OPEN') DEFAULT NULL,
  `updated_at` datetime(6) DEFAULT NULL,
  `updated_by` varchar(100) DEFAULT NULL,
  `view_count` bigint DEFAULT NULL,
  `work_mode` enum('HYBRID','OFFICE','REMOTE') DEFAULT NULL,
  `working_type` enum('CONTRACT','FREELANCE','FULL_TIME','INTERNSHIP','PART_TIME') DEFAULT NULL,
  `company_id` bigint DEFAULT NULL,
  `job_category` bigint DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `FKrtmqcrktb6s7xq8djbs2a2war` (`company_id`),
  KEY `FKlp0k07j85kd7l2bmcxojaj4vp` (`job_category`),
  CONSTRAINT `FKlp0k07j85kd7l2bmcxojaj4vp` FOREIGN KEY (`job_category`) REFERENCES `job_categories` (`id`),
  CONSTRAINT `FKrtmqcrktb6s7xq8djbs2a2war` FOREIGN KEY (`company_id`) REFERENCES `companies` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=92 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

