INSERT INTO `jobs` VALUES (1,2,'Tháng lương 13+, bảo hiểm chăm sóc sức khỏe toàn diện, thưởng KPI quý.','HIGH','2026-09-10 15:47:15.392026','thuhahr@gmail.com',_binary '\0',NULL,NULL,'Xây dựng hạ tầng backend vững chắc cho nền tảng ngân hàng số thế hệ mới.','2026-10-30 23:59:59.000000',5,'Gửi CV qua email tuyển dụng hoặc LinkedIn.','SENIOR','Hà Nội','Senior Java Backend Engineer (Core Banking)',_binary '',2,'Thành thạo Java và Spring Boot, có kinh nghiệm thiết kế hệ thống ngân hàng hoặc tài chính quy mô lớn, am hiểu Microservices.','Phát triển và tối ưu hóa hệ thống Core Banking, xây dựng các dịch vụ giao dịch tài chính chịu tải cao.',75000000,45000000,'2026-09-15 00:00:00.000000','OPEN','2026-09-10 15:47:15.392026','thuhahr@gmail.com',0,'HYBRID','FULL_TIME',1,4),(2,0,'Tháng lương 13+, bảo hiểm sức khỏe cao cấp, thưởng KPI quý.','HIGH','2026-09-10 16:00:27.435345','thuhahr@gmail.com',_binary '\0',NULL,NULL,'Xây dựng hệ thống ngân hàng số thế hệ mới với độ trễ thấp và độ tin cậy tuyệt đối.','2026-10-30 23:59:59.000000',5,'Gửi CV qua email hr@fintechbank.vn hoặc LinkedIn.','SENIOR','Hà Nội','Senior Java Backend Engineer (Ngân hàng số)',_binary '',2,'Thành thạo Java, Spring Boot, Microservices và tối ưu hóa hiệu năng hệ thống tài chính.','Phát triển và vận hành lõi thanh toán (Core Banking), đảm bảo tính bảo mật và chịu tải cao.',75000000,45000000,'2026-09-15 00:00:00.000000','OPEN','2026-09-10 16:00:27.435345','thuhahr@gmail.com',0,'HYBRID','FULL_TIME',1,4),(3,0,'Khám sức khỏe định kỳ, thưởng dự án y tế thông minh, du lịch hàng năm.','MEDIUM','2026-09-10 16:01:27.884358','thuhahr@gmail.com',_binary '\0',NULL,NULL,'Ứng dụng công nghệ vào y tế giúp số hóa quy trình khám chữa bệnh tại các bệnh viện lớn.','2026-10-15 23:59:59.000000',3,'Ứng tuyển trực tiếp trên website tuyển dụng của công ty.','MIDDLE','Hồ Chí Minh','Python / Django Backend Developer (Chuyển đổi số Y tế)',_binary '\0',3,'Nắm vững Python, Django/FastAPI, xử lý cơ sở dữ liệu quan hệ và phi quan hệ lớn.','