/*!40000 ALTER TABLE `match_results` DISABLE KEYS */;
INSERT INTO `match_results` VALUES (1,'gemini-2.5-flash-lite','match-explain-v1',100,'[\"Thời gian kinh nghiệm thực tế (1.3 năm) chưa đạt mức yêu cầu tối thiểu là 2 năm cho các kỹ năng bắt buộc như Java, Spring Boot, SQL & Database Design, RESTful API & Microservices, Authentication & Authorization.\", \"Thiếu bằng chứng về kinh nghiệm với CI/CD & Git.\", \"Thiếu bằng chứng về kinh nghiệm với System Design & Caching.\"]','[\"Ứng viên có thể phù hợp với vai trò Junior Backend Developer nếu công ty có lộ trình đào tạo và phát triển cho nhân viên mới.\", \"Cần xem xét liệu kinh nghiệm với các công nghệ ưu tiên (NoSQL, Docker, Message Queue) có thể bù đắp cho việc thiếu kinh nghiệm ở các kỹ năng bắt buộc hay không.\", \"Mức độ nhiệt huyết và mong muốn học hỏi của ứng viên có thể là một yếu tố quan trọng cần xem xét.\"]','2026-10-01 04:06:01.055175','Ứng viên đang theo học tại Đại học Bách khoa Hà Nội với GPA 3.4/4.0, chuyên ngành Kỹ thuật Phần mềm, phù hợp với yêu cầu về học vấn của vị trí.',100,NULL,'Ứng viên có 1.3 năm kinh nghiệm làm việc thực tế, chưa đạt yêu cầu tối thiểu 2 năm cho vị trí Kỹ Sư Phần Mềm Backend. Tuy nhiên, ứng viên đã có kinh nghiệm làm việc với các công nghệ cốt lõi như Java, Spring Boot, Microservices, cơ sở dữ liệu SQL và các công cụ như Docker, RabbitMQ.',65,'[\"Làm rõ kinh nghiệm thực tế với Java, Spring Boot và các nguyên lý Microservices để đánh giá sâu hơn mức độ đáp ứng yêu cầu 2 năm kinh nghiệm.\", \"Hỏi chi tiết về quy trình CI/CD và cách ứng viên đã sử dụng Git trong các dự án trước đây.\", \"Tìm hiểu thêm về cách ứng viên tiếp cận và giải quyết các vấn đề liên quan đến System Design và Caching.\"]',73.45,'2026-10-01 04:06:01.191077','Điểm số tổng thể là 73.45/100 cho thấy mức độ phù hợp tương đối. Ứng viên có nền tảng kỹ thuật tốt và kinh nghiệm thực tế với các công nghệ quan trọng, tuy nhiên, thời gian kinh nghiệm chưa đạt yêu cầu và còn thiếu một số kỹ năng ưu tiên như CI/CD & Git và System Design & Caching.',100,64.41,'COMPLETED','[\"Có kinh nghiệm phát triển RESTful API và tích hợp Redis để cải thiện hiệu suất truy vấn.\", \"Đã có kinh nghiệm làm việc với Microservices và Message Queue (RabbitMQ).\", \"Có kinh nghiệm sử dụng Docker để triển khai ứng dụng.\", \"Đã tham gia phát triển các tính năng liên quan đến xác thực và phân quyền.\"]','2026-10-01 04:07:29.846541','[\"Xác minh lại thời gian làm việc thực tế của ứng viên tại các công ty đã liệt kê trong CV.\", \"Yêu cầu ứng viên mô tả cụ thể hơn về các dự án đã thực hiện liên quan đến Spring Boot, Microservices, và cơ sở dữ liệu.\", \"Kiểm tra các dự án trên GitHub để đánh giá mức độ đóng góp và kỹ năng lập trình.\"]',4);
/*!40000 ALTER TABLE `match_results` ENABLE KEYS */;
UNLOCK TABLES;

