Date\":\"2026-12-31T23:59:59Z\",\"status\":\"OPEN\",\"createdAt\":\"2026-09-27T03:42:30.366662600Z\",\"deleted\":false,\"companyId\":23,\"companyName\":\"Ngân hàng TMCP Đầu tư và Phát triển Việt Nam - Khối Công nghệ\",\"companyStatus\":\"ACTIVE\",\"companyDeleted\":false,\"jobCategoryId\":4,\"jobCategoryName\":\"Backend Developer\",\"skills\":[{\"id\":359,\"skillId\":16,\"skillName\":\"Java\"},{\"id\":360,\"skillId\":17,\"skillName\":\"Spring Boot\"},{\"id\":361,\"skillId\":23,\"skillName\":\"SQL & Database Design\"},{\"id\":362,\"skillId\":24,\"skillName\":\"NoSQL Databases\"},{\"id\":363,\"skillId\":25,\"skillName\":\"RESTful API & Microservices\"},{\"id\":364,\"skillId\":26,\"skillName\":\"Docker & Kubernetes\"},{\"id\":365,\"skillId\":27,\"skillName\":\"Message Queue (RabbitMQ / Kafka)\"},{\"id\":366,\"skillId\":28,\"skillName\":\"Authentication & Authorization\"},{\"id\":367,\"skillId\":29,\"skillName\":\"CI/CD & Git\"},{\"id\":368,\"skillId\":30,\"skillName\":\"System Design & Caching\"}]}',NULL,0,'job.index.created','PENDING'),(124,'1','APPLICATION','EMAIL','2026-09-27 15:00:29.015556','15891c80-9e5d-4555-b825-404be9b6a5a8','JOB_APPLY','email.exchange',NULL,NULL,'2026-09-27 15:00:29.015556','{\"email\":\"nguyenminhanhit@gmail.com\",\"candidateName\":\"Nguyễn Minh Anh\",\"appliedAt\":\"2026-09-27T15:00:28.987757100Z\",\"jobName\":\"Kỹ Sư Phần Mềm Backend (Java / Spring Boot) - Khối Công Nghệ Ngân Hàng BIDV\",\"location\":\"Tòa nhà Tháp BIDV, 35 Hàng Vôi, Hoàn Kiếm, Hà Nội\",\"salaryMin\":1.8E7,\"salaryMax\":2.8E7,\"negotiable\":true,\"workingType\":\"FULL_TIME\",\"workMode\":\"HYBRID\",\"level\":\"JUNIOR\",\"startDate\":\"2026-09-01T00:00:00Z\",\"endDate\":\"2026-12-31T23:59:59Z\",\"companyName\":\"Ngân hàng TMCP Đầu tư và Phát triển Việt Nam - Khối Công nghệ\",\"companyLogo\":\"https://www.bidv.com.vn/logo-bidv.png\",\"hrName\":\"Nguyễn Phương Thảo\"}',NULL,0,'job.apply','PENDING'),(125,'91','JOB','JOB_INDEX','2026-09-27 15:00:29.024620','e714ed97-663c-45f4-b